  cursor: pointer;
}
</style>
</head>
<body>
<canvas id="stage"></canvas>
<div id="countdown" aria-hidden="true">3</div>

<div id="dock" role="toolbar" aria-label="Simulation Controls">
  <button id="btn-refire" type="button" aria-label="Re-fire" title="Re-fire">
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M21.5 2v6h-6M21.34 15.57a10 10 0 1 1-.57-8.38l5.67-5.19"/>
    </svg>
    <span>Re-fire</span>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <button id="btn-toggle" type="button" aria-label="Pause" title="Play / Pause">
    <svg id="icon-pause" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true">
      <rect x="6" y="4" width="4" height="16" rx="1"/>
      <rect x="14" y="4" width="4" height="16" rx="1"/>
    </svg>
    <svg id="icon-play" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true" style="display:none;">
      <path d="M8 5v14l11-7z"/>
    </svg>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <div id="speed-group" role="radiogroup" aria-label="Playback Speed">
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.25">0.25×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.5">0.5×</button>
    <button class="speed-pill is-active" type="button" role="radio" aria-checked="true" data-speed="1.0">1.0×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="2.0">2.0×</button>
  </div>
  <span class="dock-sep" aria-hidden="true"></span>
  <input id="scrubber" type="range" min="0" max="100" step="0.001" value="0" aria-label="Timeline Scrubber">
</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script id="rampart-strategy">
function createStrategy() {
  return { plan() { return []; } };
}
</script>
<script id="rampart-sim">
function rampartSimulate(createStrategy, seed, maxTicks) {
  const observe = arguments[3];
  const types = [
    ["grunt",60,10,4,1,0,1,10], ["runner",40,20,4,1,0,2,4],
    ["wisp",50,12,6,2,1,3,3], ["brute",150,6,9,3,0,4,3],
    ["splitter",90,8,6,2,0,6,2], ["mender",70,8,7,2,0,8,1],
    ["splitling",0,12,1,1,0,Infinity,0]
  ];
  const guns = [
    ["bolt",50,26,8,300,0,0,false,3], ["cannon",90,60,24,260,90,0,false,1],
    ["frost",70,10,12,240,0,30,false,3], ["lance",120,180,36,360,0,0,true,1],
    ["flak",80,40,10,320,70,0,false,2]
  ];
  const coords = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],
    [15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const routes = [
    [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]],
    [[0,6],[21,6],[21,11],[23,11]]
  ].map(route => {
    let length = 0;
    const segments = route.slice(1).map(([x,y], i) => {
      const [sx,sy] = route[i];
      const segment = [length, sx * 100 + 50, sy * 100 + 50, Math.sign(x-sx), Math.sign(y-sy)];
      length += 100 * (Math.abs(x-sx) + Math.abs(y-sy));
      return segment;
    });
    return { length, segments };
  });

  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ''^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t; return (t ''^ (t >>> 14)) >>> 0; }; }
  const draw = mulberry32(seed);
  const strategy = createStrategy();
  const slots = coords.map(([x,y], slot) => ({ slot, x: 100*x+50, y: 100*y+50, turret: null }));
  const log = [];
  let events = [], enemies = [], queue = [], nextId = 1;
  let wave = 0, tick = 0, gold = 250, baseHp = 10, fallTick = -1;
  let multiplier = 1000;
  let next = generate(1);

  function generate(w) {
    const eligible = types.filter(type => type[6] <= w);
    const total = eligible.reduce((sum, type) => sum + type[7], 0);
    return Array.from({ length: 4 + Math.floor(3*w/5) }, () => {
      let r = draw() % total;
      return eligible.find(type => (r -= type[7]) < 0);
    });
  }
  function place(e) {
    const segments = routes[e.air].segments;
    let i = segments.length - 1;
    while (segments[i][0] > e.progress) i--;
    const [from,x,y,dx,dy] = segments[i];
    e.x = x + (e.progress-from)*dx;
    e.y = y + (e.progress-from)*dy;
    e.dx = dx;
    e.dy = dy;
  }
  function spawn(type, w, maxHp, progress = 0) {
    const air = type[5];
    const armor = type[0] === "grunt" ? Math.floor(w/4) : type[0] === "brute" ? 6+w : 0;
    const e = { id: nextId++, type: type[0], hp: maxHp, maxHp, air, armor,
      speed: type[2], bounty: type[3], leak: type[4], wave: w, progress,
      length: routes[air].length, slow: 0, age: 0 };
    place(e);
    enemies.push(e);
  }
  function view(e) {
    return { id:e.id, type:e.type, hp:e.hp, maxHp:e.maxHp, x:e.x, y:e.y, air:e.air,
      armor:e.armor, speed:e.speed, slowed:e.slow, remaining:e.length-e.progress };
  }
  function emit(kind, values) {
    events.push({ kind, tick, ...values });
  }
  function apply(actions) {
    for (const a of (Array.isArray(actions) ? actions.slice(0,32) : [])) {
      if (!a || !Number.isInteger(a.slot) || a.slot < 0 || a.slot >= slots.length) continue;
      const s = slots[a.slot], t = s.turret;
      if (a.op === "build" && !t) {
        const index = guns.findIndex(gun => gun[0] === a.type);
        const gun = guns[index];
        if (!gun || gold < gun[1]) continue;
        gold -= gun[1];
        s.turret = { gun, tier:1, spent:gun[1], damage:gun[2], range:gun[4], cooldown:0 };
        log.push([tick,"B",s.slot,index]);
        if (observe) emit("build", { slot:s.slot, type:gun[0] });
      } else if (a.op === "upgrade" && t && t.tier < 3) {
        const cost = t.gun[1]*t.tier;
        if (gold < cost) continue;
        gold -= cost;
        t.spent += cost;
        t.tier++;
        t.damage = Math.floor(t.damage*16/10);
        t.range += 30;
        log.push([tick,"U",s.slot,t.tier]);
        if (observe) emit("upgrade", { slot:s.slot, type:t.gun[0] });
      } else if (a.op === "sell" && t) {
        gold += Math.floor(t.spent*70/100);
        s.turret = null;
        log.push([tick,"S",s.slot,0]);
        if (observe) emit("sell", { slot:s.slot, type:t.gun[0] });
      }
    }
  }
  function distanceSquared(x,y,e) {
    const dx = x-e.x, dy = y-e.y;
    return dx*dx+dy*dy;
  }
  function record() {
    observe(tick, {
      gold, baseHp, wave, nextWave: next.map(type => type[0]),
      turrets: slots.map(s => s.turret && { type:s.turret.gun[0], tier:s.turret.tier }),
      enemies: enemies.map(e => ({ ...view(e), dx:e.dx, dy:e.dy, age:e.age })),
      events
    });
    events = [];
  }

  for (; tick < maxTicks; tick++) {
    if (tick >= 20 && (tick-20)%40 === 0) {
      gold += Math.min(50,Math.floor(gold*5/100)) + 10 + 2*(++wave);
      if (wave > 1) multiplier = Math.floor(multiplier*108/100);
      const composition = next;
      next = generate(wave+1);
      if (observe) emit("wave", { wave });
      apply(strategy.plan({
        tick, wave, gold, baseHp,
        slots: slots.map(({slot,x,y,turret:t}) => ({
          slot,x,y,turret:t && { type:t.gun[0], tier:t.tier, spent:t.spent }
        })),
        enemies: enemies.map(view), nextWave: next.map(type => type[0])
      }));
      for (let i = 0; i < composition.length; i++) {
        const type = composition[i];
        queue.push({ tick:tick+4*i, wave, i, type, hp:Math.floor(type[1]*multiplier/1000) });
      }
      queue.sort((a,b) => a.tick-b.tick || a.wave-b.wave || a.i-b.i);
    }
    while (queue.length && queue[0].tick === tick) {
      const entry = queue.shift();
      spawn(entry.type, entry.wave, entry.hp);
    }
    for (let i = 0; i < enemies.length; i++) {
      const e = enemies[i];
      e.progress += e.slow > 0 ? Math.floor(e.speed*60/100) : e.speed;
      if (e.progress < e.length) {
        place(e);
        continue;
      }
      baseHp -= e.leak;
      enemies.splice(i--,1);
      log.push([tick,"L",e.id,baseHp]);
      if (observe) emit("leak", { type:e.type, baseHp });
      if (baseHp <= 0) {
        fallTick = tick;
        log.push([tick,"F",wave,0]);
        if (observe) emit("fall", { wave });
        break;
      }
    }
    if (fallTick >= 0) {
      if (observe) record();
      break;
    }
    for (const e of enemies) {
      e.age++;
      if (e.type !== "mender" || e.age%20 !== 0) continue;
      for (const ally of enemies) {
        if (distanceSquared(e.x,e.y,ally) <= 150*150)
          ally.hp = Math.min(ally.maxHp, ally.hp+Math.floor(ally.maxHp*8/100));
      }
      if (observe) emit("heal", { x:e.x, y:e.y });
    }
    for (const s of slots) {
      const t = s.turret;
      if (!t) continue;
      if (t.cooldown > 0 && --t.cooldown > 0) continue;
      const [type,,,period,,splash,slow,pierce,domain] = t.gun;
      const r2 = t.range*t.range;
      const candidates = enemies.filter(e => (domain & (1 << e.air)) && distanceSquared(s.x,s.y,e) <= r2);
      if (!candidates.length) continue;
      let target;
      if (strategy.target) {
        const id = strategy.target({ slot:s.slot, type, tier:t.tier, x:s.x, y:s.y, range:t.range }, candidates.map(view));
        target = candidates.find(e => e.id === id);
      }
      if (!target) {
        target = candidates[0];
        for (const e of candidates)
          if (e.length-e.progress < target.length-target.progress) target = e;
      }
      if (observe) emit("shot", { slot:s.slot, type, x:target.x, y:target.y, air:target.air, splash });
      const struck = splash ? enemies.filter(e => (domain & (1 << e.air)) &&
        distanceSquared(target.x,target.y,e) <= splash*splash) : [target];
      for (const e of struck) {
        e.hp -= Math.max(1, t.damage-(pierce ? 0 : e.armor));
        if (slow) e.slow = slow;
      }
      t.cooldown = period;
      for (let i = 0; i < enemies.length; i++) {
        const e = enemies[i];
        if (e.hp > 0) continue;
        gold += e.bounty;
        log.push([tick,"K",e.id,s.slot]);
        if (observe) emit("kill", { type:e.type, x:e.x, y:e.y, air:e.air });
        enemies.splice(i--,1);
        if (e.type === "splitter") {
          const hp = Math.max(1,Math.floor(e.maxHp/4));
          for (let n = 0; n < 3; n++) spawn(types[6],e.wave,hp,e.progress);
        }
      }
    }
    for (const e of enemies) if (e.slow > 0) e.slow--;
    if (observe) record();
  }

  let hash = 0x811c9dc5;
  const json = JSON.stringify(log);
  for (let i = 0; i < json.length; i++) hash = Math.imul(hash ''^ json.charCodeAt(i), 0x01000193);
  const score = Math.round(((fallTick < 0 ? maxTicks : fallTick)-20)/40*100)/100;
  return { score, fallTick, log, hash: (hash>>>0).toString(16).padStart(8,"0") };
}
</script>
