    [\"splitter\",90,8,6,2,0,6,2], [\"mender\",70,8,7,2,0,8,1],
    [\"splitling\",0,12,1,1,0,Infinity,0]
  ];
  const guns = [
    [\"bolt\",50,26,8,300,0,0,false,3], [\"cannon\",90,60,24,260,90,0,false,1],
    [\"frost\",70,10,12,240,0,30,false,3], [\"lance\",120,180,36,360,0,0,true,1],
    [\"flak\",80,40,10,320,70,0,false,2]
  ];
  const coords = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],
    [15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const routes = [
    [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]],
    [[0,6],[21,6],[21,11],[23,11]]
  ].map(route => {
    let length = 0;
    const segments = route.slice(1).map(([x,y], i) => {
      const [sx,sy] = route[i];
      const segment = [length, sx*100+50, sy*100+50, Math.sign(x-sx), Math.sign(y-sy)];
      length += 100 * (Math.abs(x-sx) + Math.abs(y-sy));
      return segment;
    });
    return { length, segments };
  });

  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a "'^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t; return (t ''^ (t >>> 14)) >>> 0; }; }
  const draw = mulberry32(seed);
  const strategy = createStrategy();
  const slots = coords.map(([x,y], slot) => ({ slot, x:100*x+50, y:100*y+50, turret:null }));
