    \"cannon\",\"bolt\",\"flak\",\"cannon\",\"bolt\",\"flak\",\"flak\",\"flak\"];
  const placementOrder = [0,2,1,4,3,12,7,6,11,10,15,8,5,14,13,9];
  let currentWave = 0;
  let reinforcedAir = false, reinforcedArmor = false, frozenGate = false;

  function plan({wave,gold,slots,enemies,nextWave,baseHp}) {
    currentWave = wave;
    const actions = [];
